from pathlib import Path
import base64
import subprocess
import tempfile

SOURCE_B64 = """"""

SIZES = {
    "Icon-20@2x.png": 40,
    "Icon-20@3x.png": 60,
    "Icon-29@2x.png": 58,
    "Icon-29@3x.png": 87,
    "Icon-40@2x.png": 80,
    "Icon-40@3x.png": 120,
    "Icon-60@2x.png": 120,
    "Icon-60@3x.png": 180,
    "Icon-20-ipad@1x.png": 20,
    "Icon-20-ipad@2x.png": 40,
    "Icon-29-ipad@1x.png": 29,
    "Icon-29-ipad@2x.png": 58,
    "Icon-40-ipad@1x.png": 40,
    "Icon-40-ipad@2x.png": 80,
    "Icon-76@1x.png": 76,
    "Icon-76@2x.png": 152,
    "Icon-83.5@2x.png": 167,
    "Icon-1024.png": 1024,
}


def main() -> None:
    icon_dir = Path("Resources/Assets.xcassets/AppIcon.appiconset")
    icon_dir.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory() as temp_dir:
        source = Path(temp_dir) / "os-player-icon-source.jpg"
        source.write_bytes(base64.b64decode(SOURCE_B64))
        for filename, pixels in SIZES.items():
            target = icon_dir / filename
            subprocess.run(["/usr/bin/sips", "-s", "format", "png", "-z", str(pixels), str(pixels), str(source), "--out", str(target)], check=True, stdout=subprocess.DEVNULL)
            if not target.exists() or target.stat().st_size == 0:
                raise SystemExit(f"failed to generate {target}")
    print(f"OS player icons generated: {len(SIZES)}")


if __name__ == "__main__":
    main()
